function escapeHtml(s) { const d = document.createElement('div'); d.textContent = s == null ? '' : s; return d.innerHTML; }

function renderStats(data) {
  const area = document.getElementById('stats-area');
  let html = '';

  html += '<div class="card"><h2>概览</h2>';
  html += '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:16px;margin-top:12px">';
  html += statBox('会话数', data.session_count);
  html += statBox('检索次数', data.search_count);
  html += statBox('导入次数', data.import_count);
  html += statBox('分析次数', data.analyze_count);
  html += statBox('答题次数', data.quiz_count);
  html += statBox('总事件数', data.total_events);
  html += statBox('累计学习时长', fmtStudyTime(data.study_minutes));
  html += '</div>';
  html += `<p style="margin-top:12px;font-size:13px;color:#888">数据来源: ${data.source === 'real' ? '真实使用' : '开发/测试'} | 课程: ${escapeHtml(data.course_id)} | 时区: ${escapeHtml(data.tz || 'UTC')}（按天统计与学习时长按此时区计算；真实会话时长将在 M3 接入，当前为按事件间隔的估算）</p>`;
  html += '</div>';

  if (data.daily && data.daily.length) {
    html += '<div class="card"><h2>按天趋势</h2><div id="daily-chart" style="width:100%;height:300px"></div></div>';
  } else {
    html += '<div class="card"><p style="color:#888">暂无按天趋势数据</p></div>';
  }

  area.innerHTML = html;

  if (data.daily && data.daily.length) {
    renderDailyChart(data.daily);
  }
}

function statBox(label, value) {
  return `<div style="background:#f0f4f8;border-radius:8px;padding:16px;text-align:center">
    <div style="font-size:24px;font-weight:600;color:#0b4f8a">${value}</div>
    <div style="font-size:13px;color:#666;margin-top:4px">${label}</div>
  </div>`;
}

function renderDailyChart(daily) {
  const chart = echarts.init(document.getElementById('daily-chart'));
  const dates = daily.map(d => d.date);
  chart.setOption({
    tooltip: { trigger: 'axis' },
    legend: { data: ['检索', '导入', '分析', '答题'], bottom: 0 },
    xAxis: { type: 'category', data: dates },
    yAxis: { type: 'value', minInterval: 1 },
    series: [
      { name: '检索', type: 'bar', stack: 'total', data: daily.map(d => d.search || 0), itemStyle: { color: '#0b4f8a' } },
      { name: '导入', type: 'bar', stack: 'total', data: daily.map(d => d.import || 0), itemStyle: { color: '#27ae60' } },
      { name: '分析', type: 'bar', stack: 'total', data: daily.map(d => d.analyze || 0), itemStyle: { color: '#e67e22' } },
      { name: '答题', type: 'bar', stack: 'total', data: daily.map(d => d.quiz || 0), itemStyle: { color: '#8e44ad' } },
    ],
  });
  window.addEventListener('resize', () => chart.resize());
}

